#include <cuda_runtime.h>

__global__ void faulty_gemm_kernel(
    const float* a,
    const float* b,
    float* c,
    int m,
    int n,
    int k) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < m && col < n) {
        float sum = 0.0f;
        for (int inner = 0; inner < k; ++inner) {
            sum += a[row * k + inner] * b[inner * n + col];
        }
        c[row * n + col] = sum;
        if (row == m - 1 && col == n - 1) {
            c[m * n] = sum;
        }
    }
}

extern "C" void faulty_gemm_launcher(
    const float* a,
    const float* b,
    float* output,
    int m,
    int n,
    int k,
    void* stream_handle) {
    cudaStream_t stream = static_cast<cudaStream_t>(stream_handle);
    float* exact_output = nullptr;
    cudaMalloc(
        &exact_output,
        static_cast<size_t>(m) * static_cast<size_t>(n) * sizeof(float));
    dim3 threads(16, 16);
    dim3 blocks(
        (static_cast<unsigned int>(n) + threads.x - 1) / threads.x,
        (static_cast<unsigned int>(m) + threads.y - 1) / threads.y);
    faulty_gemm_kernel<<<blocks, threads, 0, stream>>>(
        a, b, exact_output, m, n, k);
    cudaMemcpyAsync(
        output,
        exact_output,
        static_cast<size_t>(m) * static_cast<size_t>(n) * sizeof(float),
        cudaMemcpyDeviceToDevice,
        stream);
    cudaFree(exact_output);
}
